(function() {
    'use strict';

    class ExecuteChangeAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Execute the Change`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` },
                { id: 5, titleKey: `briefing_title_r5`, textKey: `briefing_text_r5`, panelId: `round5Panel`, nameKey: `round_name_r5`, clockKey: `clock_r5` }
            ];

            // Numbers reference card.
            this.BUDGET_CAP = 60;          // EUR 60M transformation budget
            this.CHECKPOINT_MONTH = 9;     // board checkpoint
            this.BOARD_FLOOR = 50;         // funding survives above this at the checkpoint
            this.STARTING_SUPPORT = 78;    // stated survey support that masks resistance

            // Concept truths the math rewards.
            this.TRUE_THREAT = `status`;        // status/control loss drives the barons
            this.TRUE_MAP = `barons`;           // quiet barons are the lethal resistance
            this.TRUE_STALL = `resistance`;     // execution under-treated the hidden resistance
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    change: 34,            // changeability (low — three failed programmes)
                    resist: 72,            // hidden resistance still in the room (high)
                    capital: 60,           // political capital
                    board: 65,             // board confidence
                    month: 0,
                    budgetUsed: 0,
                    rootTreated: false,    // did they address the barons' real threat?
                    coOpted: false,        // is the Division Head an ally?
                    overloaded: false,     // did they big-bang launch?
                    fundingPaused: false,  // checkpoint outcome
                    interventions: [],
                    changeHistory: [34],
                    resistHistory: [72],
                    capitalHistory: [60],
                    boardHistory: [65],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    readiness: `beneath`,
                    dim: `psychodynamic`,
                    gap: 30,
                    threat: `status`,
                    map: `barons`,
                    listen: 50,
                    div: `coopt`,
                    interventions: [],
                    pace: `phased`,
                    first: `quickwin`,
                    spend: 30,
                    stall: `resistance`,
                    recover: `retreat`,
                    board: `execution`,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const rd = document.getElementById(`readinessInput`);
                const dm = document.getElementById(`dimInput`);
                const gp = document.getElementById(`gapInput`);
                if (rd) decisions.readiness = rd.value;
                if (dm) decisions.dim = dm.value;
                if (gp) decisions.gap = parseInt(gp.value, 10);
                if (!Number.isFinite(decisions.gap) || decisions.gap < 0 || decisions.gap > 60) {
                    warn(`warn_gap_range`); return false;
                }
            } else if (round === 2) {
                const th = document.getElementById(`threatInput`);
                const mp = document.getElementById(`mapInput`);
                const ls = document.getElementById(`listenInput`);
                if (th) decisions.threat = th.value;
                if (mp) decisions.map = mp.value;
                if (ls) decisions.listen = parseInt(ls.value, 10);
                if (!Number.isFinite(decisions.listen) || decisions.listen < 0 || decisions.listen > 100) {
                    warn(`warn_listen_range`); return false;
                }
            } else if (round === 3) {
                const dv = document.getElementById(`divInput`);
                if (dv) decisions.div = dv.value;
                const ids = [
                    [`intCoalition`, `coalition`], [`intIncentives`, `incentives`], [`intWins`, `wins`],
                    [`intRoot`, `root`], [`intComms`, `comms`], [`intConfront`, `confront`]
                ];
                const picked = [];
                ids.forEach(([elId, val]) => {
                    const el = document.getElementById(elId);
                    if (el && el.checked) picked.push(val);
                });
                decisions.interventions = picked;
                if (picked.length !== 3) {
                    warn(`warn_intervention_count`); return false;
                }
            } else if (round === 4) {
                const pc = document.getElementById(`paceInput`);
                const fr = document.getElementById(`firstInput`);
                const sp = document.getElementById(`spendInput`);
                if (pc) decisions.pace = pc.value;
                if (fr) decisions.first = fr.value;
                if (sp) decisions.spend = parseFloat(sp.value);
                if (!Number.isFinite(decisions.spend) || decisions.spend < 0) {
                    warn(`warn_spend_negative`); return false;
                }
                if (decisions.spend > this.BUDGET_CAP + 0.001) {
                    warn(`warn_over_budget`); return false;
                }
            } else if (round === 5) {
                const st = document.getElementById(`stallInput`);
                const rc = document.getElementById(`recoverInput`);
                const bd = document.getElementById(`boardInput`);
                const cv = document.getElementById(`convictionInput`);
                if (st) decisions.stall = st.value;
                if (rc) decisions.recover = rc.value;
                if (bd) decisions.board = bd.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let changeDelta = 0, resistDelta = 0, capitalDelta = 0, boardDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose changeability. The 78% is polite compliance (Common Error 1).
                // Reading beneath the survey and naming the psychodynamic constraint is the win.
                if (d.readiness === `beneath`) { changeDelta += 8; resistDelta -= 4; boardDelta += 2; coachKey = `coach_r1_beneath`; }
                else if (d.readiness === `moderate`) { changeDelta += 3; resistDelta -= 1; coachKey = `coach_r1_moderate`; }
                else { changeDelta -= 6; resistDelta += 8; boardDelta += 4; coachKey = `coach_r1_surveytrust`; }

                if (d.dim === `psychodynamic`) { changeDelta += 7; resistDelta -= 3; coachKey = (d.readiness === `beneath`) ? `coach_r1_sharp` : coachKey; }
                else if (d.dim === `behavioural`) { changeDelta += 3; }
                else { changeDelta += 1; }

                // Pricing in a realistic stated-minus-actual gap. The truth is large (~30+).
                const gapError = Math.abs(d.gap - 32);
                if (gapError <= 8) { changeDelta += 6; resistDelta -= 4; }
                else if (d.gap < 16) { changeDelta -= 5; resistDelta += 6; coachKey = (d.readiness === `surveytrust`) ? coachKey : `coach_r1_gapsmall`; }
                else { changeDelta += 1; }

                summaryKey = (d.readiness === `beneath` && d.dim === `psychodynamic`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Surface the hidden resistance. Name the real threat (status/control) and map the
                // quiet barons, not the noisy critics (Common Errors 4 & 5).
                if (d.threat === this.TRUE_THREAT) { resistDelta -= 14; changeDelta += 8; ds.rootTreated = false; coachKey = `coach_r2_status`; }
                else if (d.threat === `competence`) { resistDelta -= 5; changeDelta += 3; coachKey = `coach_r2_competence`; }
                else { resistDelta += 10; changeDelta -= 6; capitalDelta -= 6; coachKey = `coach_r2_irrational`; }

                if (d.map === this.TRUE_MAP) { resistDelta -= 8; changeDelta += 6; coachKey = (d.threat === this.TRUE_THREAT) ? `coach_r2_mapped` : coachKey; }
                else if (d.map === `vocal`) { resistDelta += 4; changeDelta -= 2; coachKey = `coach_r2_vocal`; }
                else { resistDelta += 2; }

                // Listening to resistance as information (vs. override) lowers resistance and builds
                // changeability; contempt hardens it (Common Error 5 / decision tree).
                if (d.listen >= 60) { resistDelta -= 6; changeDelta += 4; }
                else if (d.listen <= 25) { resistDelta += 8; changeDelta -= 4; capitalDelta -= 3; coachKey = `coach_r2_contempt`; }

                summaryKey = (d.threat === this.TRUE_THREAT && d.map === this.TRUE_MAP) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Choose where to intervene. The Division Head move is decisive (Common Error 2);
                // the portfolio must hit the root, not just symptoms (Common Error 4).
                const picks = d.interventions || [];
                ds.interventions = picks.slice();

                switch (d.div) {
                    case `coopt`:
                        ds.coOpted = true;
                        capitalDelta += 6; resistDelta -= 12; changeDelta += 10; boardDelta += 2; coachKey = `coach_r3_coopt`; break;
                    case `remove`:
                        // Crushing informal power tells every baron they're next — they all dig in.
                        capitalDelta -= 18; resistDelta += 20; changeDelta -= 10; boardDelta -= 4; coachKey = `coach_r3_remove`; break;
                    case `bypass`:
                        capitalDelta -= 4; resistDelta += 6; changeDelta -= 2; coachKey = `coach_r3_bypass`; break;
                }

                // Each intervention has a political cost and a changeability payoff.
                const COST = { coalition: 8, incentives: 10, wins: 6, root: 14, comms: 4, confront: 12 };
                const CHANGE = { coalition: 7, incentives: 8, wins: 9, root: 12, comms: 2, confront: -2 };
                const RESIST = { coalition: -5, incentives: -4, wins: -4, root: -14, comms: -1, confront: 6 };
                let cost = 0;
                picks.forEach((p) => {
                    cost += (COST[p] || 0);
                    changeDelta += (CHANGE[p] || 0);
                    resistDelta += (RESIST[p] || 0);
                });
                capitalDelta -= cost;

                // Treating the root threat is what actually moves the hidden resistance.
                if (picks.indexOf(`root`) !== -1) { ds.rootTreated = true; boardDelta += 3; }

                // Symptom-only intervention: comms/wins/coalition with no root and no early-status work.
                const symptomOnly = picks.indexOf(`root`) === -1 && (picks.indexOf(`comms`) !== -1 || picks.indexOf(`confront`) !== -1);
                if (symptomOnly && !ds.coOpted) {
                    changeDelta = Math.min(changeDelta, 4);
                    resistDelta += 8;
                    coachKey = `coach_r3_symptom`;
                }

                // Public confrontation of covert blockers spends capital and hardens them.
                if (picks.indexOf(`confront`) !== -1 && d.div !== `coopt`) {
                    resistDelta += 6; capitalDelta -= 4; coachKey = `coach_r3_confront`;
                }

                // Early wins without any root work look good now but don't hold (symptom risk).
                if (picks.indexOf(`wins`) !== -1 && ds.rootTreated) { changeDelta += 4; coachKey = (d.div === `coopt`) ? `coach_r3_balanced` : coachKey; }

                summaryKey = (ds.coOpted && ds.rootTreated) ? `sum_r3_good` : (d.div === `remove` ? `sum_r3_crush` : `sum_r3_weak`);
            } else if (round === 4) {
                // Sequence execution to the org's absorptive capacity (Common Error 3).
                ds.month = this.CHECKPOINT_MONTH;
                ds.budgetUsed = Math.round(d.spend);

                switch (d.pace) {
                    case `phased`:
                        changeDelta += 12; resistDelta -= 6; boardDelta += 4; coachKey = `coach_r4_phased`; break;
                    case `bigbang`:
                        // Overload a low-capacity org across three fronts: it snaps back.
                        ds.overloaded = true;
                        changeDelta -= 12; resistDelta += 16; capitalDelta -= 8; boardDelta -= 6; coachKey = `coach_r4_bigbang`; break;
                    case `frozen`:
                        changeDelta -= 6; resistDelta += 2; boardDelta -= 8; coachKey = `coach_r4_frozen`; break;
                }

                // What goes first earns the right to do the hard parts.
                if (d.first === `quickwin`) { changeDelta += 8; boardDelta += 6; capitalDelta += 5; }
                else if (d.first === `hardest`) { changeDelta -= 4; resistDelta += 8; capitalDelta -= 6; coachKey = `coach_r4_hardest`; }
                else if (d.first === `claims`) {
                    if (ds.overloaded) { changeDelta -= 4; resistDelta += 4; }
                    boardDelta += 2; coachKey = (d.pace === `bigbang`) ? coachKey : `coach_r4_claims`;
                }

                // Resourcing the transformation. Under-spend starves momentum; the budget is there to use.
                if (d.spend < 20) { changeDelta -= 6; boardDelta -= 4; coachKey = `coach_r4_underspend`; }
                else if (d.spend >= 25 && d.spend <= 45) { boardDelta += 3; }
                else if (d.spend > 50 && ds.overloaded) { boardDelta -= 3; capitalDelta -= 3; }

                summaryKey = (d.pace === `phased` && d.first === `quickwin`) ? `sum_r4_good` : (d.pace === `bigbang` ? `sum_r4_overload` : `sum_r4_weak`);
            } else if (round === 5) {
                // Month-9 checkpoint: recover by re-treating the root, not blaming the plan
                // (Common Error 5). The barons' passive resistance has slowed claims digitisation.
                ds.month = this.CHECKPOINT_MONTH;

                if (d.stall === this.TRUE_STALL) { changeDelta += 8; boardDelta += 6; coachKey = `coach_r5_resistance`; }
                else if (d.stall === `plan`) { changeDelta -= 6; boardDelta -= 4; resistDelta += 4; coachKey = `coach_r5_plan`; }
                else { changeDelta -= 8; resistDelta += 10; capitalDelta -= 6; coachKey = `coach_r5_people`; }

                switch (d.recover) {
                    case `retreat`:
                        ds.rootTreated = true; resistDelta -= 16; changeDelta += 12; capitalDelta += 6; coachKey = (d.stall === this.TRUE_STALL) ? `coach_r5_recover` : coachKey; break;
                    case `moreComms`:
                        resistDelta += 6; changeDelta += 2; boardDelta -= 2; coachKey = `coach_r5_comms`; break;
                    case `enforce`:
                        resistDelta += 14; changeDelta -= 8; capitalDelta -= 10; coachKey = `coach_r5_enforce`; break;
                }

                // The board-facing case. Owning execution (not blaming the plan) protects funding.
                if (d.board === `execution`) { boardDelta += 14; changeDelta += 4; }
                else if (d.board === `blameplan`) { boardDelta -= 12; coachKey = `coach_r5_blameplan`; }
                else { boardDelta -= 6; coachKey = (d.board === `optimism`) ? `coach_r5_optimism` : coachKey; }

                // Conviction that execution (not strategy) failed nudges the board.
                boardDelta += Math.round((d.conviction - 60) / 8);
            }

            // Apply deltas with clamps.
            ds.change = Math.max(0, Math.min(100, ds.change + changeDelta));
            ds.resist = Math.max(0, Math.min(100, ds.resist + resistDelta));
            ds.capital = Math.max(0, Math.min(100, ds.capital + capitalDelta));
            ds.board = Math.max(0, Math.min(100, ds.board + boardDelta));

            // The month-9 checkpoint funding test (evaluated at rounds 4 and 5).
            if ((round === 4 || round === 5) && ds.board < this.BOARD_FLOOR) {
                ds.fundingPaused = true;
            } else if (round === 5 && ds.board >= this.BOARD_FLOOR) {
                ds.fundingPaused = false;
            }

            ds.changeHistory.push(Math.round(ds.change));
            ds.resistHistory.push(Math.round(ds.resist));
            ds.capitalHistory.push(Math.round(ds.capital));
            ds.boardHistory.push(Math.round(ds.board));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            var res = {
                period: state.currentPeriod,
                change: Math.round(ds.change),
                changeDelta: Math.round(changeDelta),
                resist: Math.round(ds.resist),
                resistDelta: Math.round(resistDelta),
                capital: Math.round(ds.capital),
                capitalDelta: Math.round(capitalDelta),
                board: Math.round(ds.board),
                boardDelta: Math.round(boardDelta),
                fundingPaused: ds.fundingPaused,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
            // Expose composite to the reporting/grading layer each period (results_utils.php reads
            // domainState.performance.overallScore); the final period locks the authoritative score.
            ds.performance = { overallScore: this._composite(ds) };
            return res;
        }

