        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.changeHistory.map((_, i) => (i === 0 ? `Start` : `R` + i));
            return {
                execChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.changeHistory },
                        { data: ds.resistHistory },
                        { data: ds.capitalHistory },
                        { data: ds.boardHistory }
                    ]
                }
            };
