        // Shared composite (0-100). Single source of truth for the per-period score written to
        // domainState.performance.overallScore (reporting/grading layer) AND the debrief. Weights
        // identical to v1.0.0.
        _composite(ds) {
            var change = Math.round(ds.change || 0), resist = Math.round(ds.resist || 0);
            var capital = Math.round(ds.capital || 0), board = Math.round(ds.board || 0);
            return Math.max(0, Math.min(100, Math.round(change * 0.35 + (100 - resist) * 0.30 + board * 0.20 + capital * 0.15)));
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const change = Math.round(ds.change), resist = Math.round(ds.resist);
            const capital = Math.round(ds.capital), board = Math.round(ds.board);

            // The mandate: land the change three programmes couldn't — high changeability, the
            // hidden resistance surfaced and lowered, and the board's funding intact.
            const fundingHeld = !ds.fundingPaused && board >= this.BOARD_FLOOR;
            const resistanceBroken = resist <= 40;
            const composite = this._composite(ds);

            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };

            // Grade band -> localized label (thresholds identical to v1.0.0).
            let performanceKey = `grade_number4`;
            if (fundingHeld && resistanceBroken && change >= 65 && composite >= 70) performanceKey = `grade_landed`;
            else if (fundingHeld && change >= 55 && resist <= 55 && composite >= 58) performanceKey = `grade_ontrack`;
            else if (fundingHeld && composite >= 45) performanceKey = `grade_surface`;
            else if (!fundingHeld) performanceKey = `grade_paused`;
            const performance = T(performanceKey);

            const insights = [];
            if (fundingHeld && resistanceBroken && change >= 65) insights.push(window.mySimulation.t(`insight_landed`));
            else if (fundingHeld && !resistanceBroken) insights.push(window.mySimulation.t(`insight_compliance`));
            else if (!fundingHeld) insights.push(window.mySimulation.t(`insight_paused`));
            else insights.push(window.mySimulation.t(`insight_partial`));

            if (!ds.rootTreated) insights.push(window.mySimulation.t(`insight_rootuntreated`));
            if (!ds.coOpted) insights.push(window.mySimulation.t(`insight_division`));
            if (ds.overloaded) insights.push(window.mySimulation.t(`insight_overload`));
            if (capital < 30) insights.push(window.mySimulation.t(`insight_capitalspent`));
            if (fundingHeld && resistanceBroken && ds.rootTreated && ds.coOpted) insights.push(window.mySimulation.t(`insight_changeability`));

            return {
                change: change,
                resist: resist,
                capital: capital,
                board: board,
                fundingHeld: fundingHeld,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var s = summary || {};
            var score = (typeof s.totalScore === 'number') ? s.totalScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            var grade = s.performance || (s.performanceKey ? T(s.performanceKey) : '');
            var held = !!s.fundingHeld;
            var badge = held
                ? '<span class="ec-cm-badge ec-cm-yes">' + T('cm_fundingheld') + '</span>'
                : '<span class="ec-cm-badge ec-cm-no">' + T('cm_fundingpaused') + '</span>';
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var metrics = ''
                + '<div class="ec-cm-metric"><span class="ec-cm-mv">' + Math.round(s.change||0) + '</span><span class="ec-cm-ml">' + T('cm_m_change') + '</span></div>'
                + '<div class="ec-cm-metric"><span class="ec-cm-mv">' + Math.round(s.resist||0) + '</span><span class="ec-cm-ml">' + T('cm_m_resist') + '</span></div>'
                + '<div class="ec-cm-metric"><span class="ec-cm-mv">' + Math.round(s.board||0) + '</span><span class="ec-cm-ml">' + T('cm_m_board') + '</span></div>'
                + '<div class="ec-cm-metric"><span class="ec-cm-mv">' + Math.round(s.capital||0) + '</span><span class="ec-cm-ml">' + T('cm_m_capital') + '</span></div>';
            return ''
                + '<div class="ec-completion">'
                +   '<div class="ec-cm-head">'
                +     '<div class="ec-cm-score">' + score + '<span class="ec-cm-score-max">/100</span></div>'
                +     '<div class="ec-cm-grade">' + grade + ' ' + badge + '</div>'
                +   '</div>'
                +   '<div class="ec-cm-metrics">' + metrics + '</div>'
                +   '<div class="ec-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="ec-cm-insights">' + items + '</ul>'
                + '</div>';
        }

